package com.commoditytrading.model;

/**
 * One request (заявка): one complete trade or order operation coming from one source.
 *
 * <p>Identity is immutable: the source, the request's number within that source and the
 * generation time never change. Only the status and the timestamps that follow from it change,
 * and only through the four transition methods, which reject an illegal order of events.
 *
 * <p>Following the course manual, a request is labelled "source.number": request {@code 2.3} is
 * the third request generated by source 2.
 */
public final class Request {

    private final int sourceId;
    private final int sequenceNumber;
    private final double generationTime;

    private RequestStatus status = RequestStatus.WAITING;
    private double serviceStartTime = Double.NaN;
    private double serviceEndTime = Double.NaN;
    private double refusalTime = Double.NaN;

    public Request(int sourceId, int sequenceNumber, double generationTime) {
        if (sourceId < 1) {
            throw new IllegalArgumentException("sourceId must be >= 1, got " + sourceId);
        }
        if (sequenceNumber < 1) {
            throw new IllegalArgumentException("sequenceNumber must be >= 1, got " + sequenceNumber);
        }
        if (generationTime < 0) {
            throw new IllegalArgumentException("generationTime must be >= 0, got " + generationTime);
        }
        this.sourceId = sourceId;
        this.sequenceNumber = sequenceNumber;
        this.generationTime = generationTime;
    }

    /** WAITING → IN_SERVICE. Called when a device takes this request. */
    public void markServiceStarted(double time) {
        requireStatus(RequestStatus.WAITING, "start service");
        requireNotBefore(time, generationTime, "service start");
        this.serviceStartTime = time;
        this.status = RequestStatus.IN_SERVICE;
    }

    /** IN_SERVICE → SERVED. Called when the device finishes this request. */
    public void markServed(double time) {
        requireStatus(RequestStatus.IN_SERVICE, "finish service");
        requireNotBefore(time, serviceStartTime, "service end");
        this.serviceEndTime = time;
        this.status = RequestStatus.SERVED;
    }

    /** WAITING → REFUSED. Called when Д1ОО2 evicts this request from a full buffer. */
    public void markRefused(double time) {
        requireStatus(RequestStatus.WAITING, "refuse");
        requireNotBefore(time, generationTime, "refusal");
        this.refusalTime = time;
        this.status = RequestStatus.REFUSED;
    }

    /** Time spent in the buffer before service (T_БП). Defined once service has started. */
    public double getWaitingTime() {
        requireStarted();
        return serviceStartTime - generationTime;
    }

    /** Time spent on the device (T_обсл). Defined once the request is served. */
    public double getServiceTime() {
        requireServed();
        return serviceEndTime - serviceStartTime;
    }

    /** Total time in the system (T_преб = T_БП + T_обсл). Defined once the request is served. */
    public double getTimeInSystem() {
        requireServed();
        return serviceEndTime - generationTime;
    }

    public int getSourceId() {
        return sourceId;
    }

    public int getSequenceNumber() {
        return sequenceNumber;
    }

    public double getGenerationTime() {
        return generationTime;
    }

    public RequestStatus getStatus() {
        return status;
    }

    public double getServiceStartTime() {
        return serviceStartTime;
    }

    public double getServiceEndTime() {
        return serviceEndTime;
    }

    public double getRefusalTime() {
        return refusalTime;
    }

    /** "source.number", for example "2.3". */
    public String getLabel() {
        return sourceId + "." + sequenceNumber;
    }

    @Override
    public String toString() {
        return "Request " + getLabel() + " [" + status + ", generated at " + generationTime + "]";
    }

    private void requireStatus(RequestStatus expected, String action) {
        if (status != expected) {
            throw new IllegalStateException(
                    "Cannot " + action + " request " + getLabel() + ": status is " + status
                            + ", expected " + expected);
        }
    }

    private void requireStarted() {
        if (status != RequestStatus.IN_SERVICE && status != RequestStatus.SERVED) {
            throw new IllegalStateException("Request " + getLabel() + " has not started service");
        }
    }

    private void requireServed() {
        if (status != RequestStatus.SERVED) {
            throw new IllegalStateException("Request " + getLabel() + " has not been served");
        }
    }

    private static void requireNotBefore(double time, double earliest, String what) {
        if (time < earliest) {
            throw new IllegalArgumentException(
                    what + " time " + time + " is before " + earliest);
        }
    }
}